import json, os, sys
D = os.path.dirname(os.path.abspath(__file__))
PREFIX = "Flat vector cartoon sticker art for a cute 2D side-scrolling mobile game: thick uniform dark-purple outlines (#2b2233) around every shape, flat color fills with exactly one hard-edged cel-shade step, no gradients, no texture, warm sunset palette of coral, peach, cream, lavender and teal accents, clean bold graphic shapes readable at small size, strict side view orthographic elevation, transparent background, absolutely no text, no letters, no numbers, no digits, no logos, no brand trade dress."
TAIL = " One single isolated game obstacle prop, centered on the canvas with generous empty transparent margin, nothing else in the image: no ground line, no floor, no cast shadow, no drop shadow, no background scenery, no sky."
P = {
 "filebox": ("1:1", "Subject: a stack of exactly two brown cardboard file storage boxes, one sitting squarely on top of the other, seen exactly from the side in flat elevation. Each box has a slightly overhanging lid, a strip of cream packing tape running over the lid edge and down the front, and a small oval hand-hold cutout. Plain kraft-brown cardboard, no labels, no writing, no barcodes. The whole stack is slightly taller than wide (proportion about 8 wide by 9 tall)."),
 "chair": ("1:1", "Subject: a rolling office chair seen exactly from the side in profile, facing right: a teal padded seat cushion, a LOW short padded backrest at the left end of the seat, one small armrest, a single central chrome gas-lift column, and a star base seen from the side so that exactly three small dark caster wheels are visible along the bottom. Dark grey plastic and chrome. Silhouette about as wide as tall (about 9 wide by 10 tall)."),
 "banner": ("1:1", "Subject: a big red hanging cloth banner seen from the front, completely blank plain red fabric with absolutely no writing or symbols on it, a golden yellow fringe of tassels along the bottom edge, a few soft vertical fold creases, its top edge wrapped around a thin horizontal rod. Two thin dark metal poles rise straight up from the two top corners of the banner to the very top of the image, as if the banner hangs from the ceiling. The red cloth itself is square (as wide as tall) and fills most of the image; the poles above it are short."),
 "wetsign": ("9:16", "Subject: a yellow plastic A-frame wet floor caution sign standing upright, seen from the front: a tall narrow yellow panel with a rounded top and a small handle cutout at the top, the two legs splaying slightly at the bottom. In the middle of the panel there is only one simple black pictogram of a stick-figure person slipping and falling backward over little wavy water lines. No words, no exclamation mark, no other marks. Silhouette tall and narrow (about 3 wide by 5 tall)."),
 "puddle": ("16:9", "Subject: a shallow flat puddle of clear blue water lying on the ground, seen from a very low side angle so it appears as a very thin, wide, flat ellipse, about seven times wider than tall, with a slightly irregular soft wavy outline, a lighter cyan inner area, and two or three small white curved highlight streaks. Only the puddle shape itself, no ground or pavement around it."),
 "cone": ("3:4", "Subject: an orange traffic cone standing upright, seen exactly from the side: a tapered cone with a slightly rounded tip, two white reflective bands around its body, and a flat square dark-orange base plate at the bottom. Silhouette about 2 wide by 3 tall."),
 "shopbar": ("3:4", "Subject: a low-hanging street shop sign obstacle, composed from top to bottom: at the very top, the front edge of a fabric awning with red and cream vertical stripes and a scalloped lower edge spanning the full width; directly under it a dark metal bracket bar; from the bracket two short chains hold a wide horizontal rectangular signboard. The signboard is a blank warm orange board with a cream inner border and only one simple centered icon of a skewer of three round brown-red meatballs on a stick, no writing at all. Overall silhouette slightly taller than wide (about 7 wide by 8.6 tall), the signboard being the largest part."),
 "step": ("16:9", "Subject: a wide low raised stone curb block / step you can stand on, a long horizontal rectangular slab exactly four times wider than tall, perfectly flat level top surface, slightly rounded top corners, made of warm light grey-beige stone with a cream highlight strip along the top edge and two thin vertical seams dividing it into three blocks. Seen exactly from the side (front elevation), no perspective, no top face visible."),
 "scaffold": ("3:4", "Subject: one section of construction scaffolding seen in flat front elevation: a rectangular frame of grey metal pipes (two vertical uprights, top and middle horizontal ledgers, one diagonal brace) covered by a draped green mesh safety net with a fine diamond net pattern, and along the bottom edge a horizontal board painted with diagonal yellow and black warning stripes. Overall silhouette about 3 wide by 4 tall."),
 "manhole": ("16:9", "Subject: an open street manhole seen from a very low side angle: on the left a very flat dark purple-black ellipse hole lying in the ground plane with a thin grey concrete rim (about five times wider than tall), and just to its right the round heavy dark-grey iron manhole cover lying flat on the ground, also appearing as a thin flat disc ellipse with a visible edge thickness and a simple grid tread pattern. Only these two objects side by side, no surrounding pavement, overall shape very wide and flat."),
 "warnSign": ("9:16", "Subject: a yellow triangular construction warning sign with a thick dark border and rounded corners, mounted on a short dark metal post with a small flat cross-leg base. Inside the triangle only one simple black pictogram of a worker digging with a shovel beside a small dirt pile. No words, no exclamation mark, no other marks. Front elevation. Overall silhouette tall and narrow (about 3 wide by 5 tall)."),
 "coin": ("1:1", "Subject: a single shiny gold coin in FRONT view (face-on, this one item is not a side view): a perfect circle with a thick raised rim, a simple raised five-pointed star embossed in the center, warm golden yellow with one darker amber cel-shade step and a small cream shine highlight at the upper left. No symbols, no letters, no numbers, no squares, no holes."),
 "bun": ("4:3", "Subject: a single white Chinese steamed bun (baozi) seen from the side: a soft rounded dome with a flat bottom, slightly wider than tall (about 6 wide by 5 tall), with twisted pleats gathered into a small swirl knot at the top center, cream-white with a soft peach cel-shade step. No plate, no steamer basket, no steam."),
}
ids = sys.argv[1:] or list(P)
for k in ids:
    ar, body = P[k]
    req = {"command": "image.generate", "args": [{"prompt": PREFIX + " " + body + TAIL, "model": "gpt-image-2.5-flare", "quality": "medium", "aspectRatio": ar, "imageSize": "2K", "background": "transparent", "name": k}]}
    with open(os.path.join(D, k + ".json"), "w", encoding="utf-8") as f:
        json.dump(req, f, ensure_ascii=False)
print("ok", ids)
